<script setup>import { ref } from 'vue'; defineProps({ articles: Array, history: Array, currentArticle: Object }); defineEmits(['select']); const view = ref('articles')</script>
<template><div class="article-sidebar"><nav class="side-links"><button @click="view='articles'">⌂　首页</button><button @click="view='articles'">▧　我的文章</button><button disabled>☑　我的笔记</button><button :class="{ activeLink: view === 'history' }" @click="view='history'">◷　阅读历史</button></nav><template v-if="view === 'articles'"><div class="side-title">经典选读 <small>×</small></div><button v-for="article in articles" :key="article.id" :class="{ active: currentArticle.id === article.id }" @click="$emit('select', article)"><strong>{{ article.title }}</strong><small>{{ article.author }} · {{ article.dynasty }}</small></button><div v-if="!articles.length" class="no-article">没有匹配的篇目</div><a>＋ 更多文章</a></template><template v-else><div class="side-title">最近阅读</div><button v-for="article in history" :key="article.id" :class="{ active: currentArticle.id === article.id }" @click="$emit('select', article)"><strong>{{ article.title }}</strong><small>{{ article.author }} · {{ article.dynasty }}</small></button><div v-if="!history.length" class="no-article">暂无阅读历史</div></template><p>“文不离句，句不离篇，<br>篇不离人，人不离世。”</p></div></template>
